package io.github.long0823.tclbondriver;
import java.io.*;import java.util.Arrays;
/** One PAT program and only its elementary/PCR/CA PIDs; generic IPTV clients need no SID option. */
final class IptvProgram {
 private final int expectedTsid,service;private final byte[] packet=new byte[188];private boolean[] allowed=new boolean[8192];private int pmt=-1,version,cc;
 private interface Section {void complete(byte[] data,int length)throws IOException;}
 private static final class Assembler {final byte[] bytes=new byte[1024];int used,needed=-1;void reset(){used=0;needed=-1;}void feed(byte[] data,int at,int end,Section callback)throws IOException{while(at<end){if(used==0&&(data[at]&255)==255)return;if(used>=bytes.length){reset();return;}bytes[used++]=data[at++];if(used==3){needed=3+(((bytes[1]&15)<<8)|(bytes[2]&255));if(needed<12||needed>bytes.length){reset();return;}}if(needed>0&&used==needed){if(crc(bytes,0,needed)==0)callback.complete(bytes,needed);reset();}}}void packet(byte[] data,int at,Section callback)throws IOException{int control=(data[at+3]>>4)&3;if(control==0||control==2)return;int pos=at+4;if(control==3)pos+=1+(data[pos]&255);if(pos>=at+188)return;if((data[at+1]&64)!=0){int pointer=data[pos++]&255;if(pos+pointer>at+188){reset();return;}if(pointer>0&&used>0)feed(data,pos,pos+pointer,callback);pos+=pointer;reset();}if(pos<at+188)feed(data,pos,at+188,callback);}}
 private final Assembler pat=new Assembler(),pmtSection=new Assembler();
 IptvProgram(int tsid,int sid){expectedTsid=tsid;service=sid;common(allowed);}
 private static void common(boolean[] set){for(int pid:new int[]{0,1,0x10,0x12,0x14,0x24,0x27,8191})set[pid]=true;}
 private static int crc(byte[] bytes,int offset,int length){int value=-1;for(int i=offset;i<offset+length;i++){value^=(bytes[i]&255)<<24;for(int bit=0;bit<8;bit++)value=(value&0x80000000)!=0?(value<<1)^0x04c11db7:value<<1;}return value;}
 private static int u16(byte[] b,int at){return ((b[at]&255)<<8)|(b[at+1]&255);}
 private void pat(byte[] b,int length)throws IOException{if(b[0]!=0||(b[5]&1)==0)return;if(u16(b,3)!=expectedTsid)throw new IOException("Tuner changed to another multiplex");version=b[5]&255;for(int pos=8;pos+4<=length-4;pos+=4)if(u16(b,pos)==service){int next=u16(b,pos+2)&8191;if(next!=pmt){pmt=next;pmtSection.reset();allowed=new boolean[8192];common(allowed);allowed[pmt]=true;}return;}}
 private static void descriptors(byte[] b,int pos,int end,boolean[] keep)throws IOException{while(pos+2<=end){int tag=b[pos]&255,len=b[pos+1]&255;if(pos+2+len>end)throw new IOException("Invalid PMT descriptors");if(tag==9&&len>=4)keep[u16(b,pos+4)&8191]=true;pos+=2+len;}if(pos!=end)throw new IOException("Invalid PMT descriptor tail");}
 private void pmt(byte[] b,int length)throws IOException{if(b[0]!=2||length<16||u16(b,3)!=service||(b[5]&1)==0)return;boolean[] keep=new boolean[8192];common(keep);keep[pmt]=true;keep[u16(b,8)&8191]=true;int info=u16(b,10)&4095,end=length-4,pos=12+info;if(pos>end)throw new IOException("Invalid PMT length");descriptors(b,12,pos,keep);while(pos+5<=end){keep[u16(b,pos+1)&8191]=true;int next=pos+5+(u16(b,pos+3)&4095);if(next>end)throw new IOException("Invalid PMT ES length");descriptors(b,pos+5,next,keep);pos=next;}if(pos!=end)throw new IOException("Invalid PMT tail");allowed=keep;}
 void packet(byte[] input,int at,OutputStream out)throws IOException{int pid=((input[at+1]&31)<<8)|(input[at+2]&255);if(pid!=0){if(pid==pmt)pmtSection.packet(input,at,this::pmt);if(allowed[pid])out.write(input,at,188);return;}pat.packet(input,at,this::pat);if(pmt<0)return;Arrays.fill(packet,(byte)255);packet[0]=0x47;packet[1]=0x40;packet[2]=0;packet[3]=(byte)(0x10|(cc++&15));packet[4]=0;packet[5]=0;packet[6]=(byte)0xb0;packet[7]=13;packet[8]=(byte)(expectedTsid>>8);packet[9]=(byte)expectedTsid;packet[10]=(byte)(version|1);packet[11]=0;packet[12]=0;packet[13]=(byte)(service>>8);packet[14]=(byte)service;packet[15]=(byte)(0xe0|(pmt>>8));packet[16]=(byte)pmt;int checksum=crc(packet,5,12);for(int i=0;i<4;i++)packet[17+i]=(byte)(checksum>>(24-i*8));out.write(packet);}
}